SELECT w.*, wr.status AS review_status, wr.rejection_reason AS review_reason, wr.reviewer_uuid, wr.submitted_at AS review_submitted_at, wr.reviewed_at, COALESCE(NULLIF(author_archive.nickname, ''), w.author) AS author_display FROM work w LEFT JOIN work_review wr ON wr.work_id = w.id LEFT JOIN user_archive author_archive ON author_archive.uuid = w.author
AND w.status = #{status}
AND (w.id LIKE CONCAT('%', #{keyword}, '%') OR w.title LIKE CONCAT('%', #{keyword}, '%') OR (w.is_claim = 1 AND author_archive.nickname LIKE CONCAT('%', #{keyword}, '%')) OR (w.is_claim = 0 AND w.author_nickname LIKE CONCAT('%', #{keyword}, '%')))
ORDER BY w.${sortField} ${sortOrder}
ORDER BY w.created_at DESC
LIMIT #{offset}, #{limit}

SELECT w.*, wr.status AS review_status, wr.rejection_reason AS review_reason, wr.reviewer_uuid, wr.submitted_at AS review_submitted_at, wr.reviewed_at, COALESCE(NULLIF(author_archive.nickname, ''), w.author) AS author_display FROM work w JOIN work_review wr ON wr.work_id = w.id LEFT JOIN user_archive author_archive ON author_archive.uuid = w.author
wr.status = #{review_status}
AND (w.id LIKE CONCAT('%', #{keyword}, '%') OR w.title LIKE CONCAT('%', #{keyword}, '%') OR (w.is_claim = 1 AND author_archive.nickname LIKE CONCAT('%', #{keyword}, '%')) OR (w.is_claim = 0 AND w.author_nickname LIKE CONCAT('%', #{keyword}, '%')))
ORDER BY wr.submitted_at ASC, w.created_at ASC LIMIT #{offset}, #{limit}

